test('calculateBulkDiscount with qty < 10', () => {
  assert.equal(calculateBulkDiscount(1000, 1), 0);
  assert.equal(calculateBulkDiscount(1000, 5), 0);
  assert.equal(calculateBulkDiscount(1000, 9), 0);
});

test('calculateBulkDiscount with qty >= 10', () => {
  // 1000 * 2.5% = 25
  assert.equal(calculateBulkDiscount(1000, 10), 25);
  assert.equal(calculateBulkDiscount(1000, 100), 25);
});

test('calculateBulkDiscount with rounding', () => {
  // 4750 * 2.5% = 118.75 -> 119 (banker's rounding)
  assert.equal(calculateBulkDiscount(4750, 10), 119);
  // 9025 * 2.5% = 225.625 -> 226 (banker's rounding)
  assert.equal(calculateBulkDiscount(9025, 10), 226);
});

test('calculateTotalLineDiscount without bulk (qty < 10)', () => {
  // lineTotal 5000, discount 5%, qty 9
  // Regular discount: 250, Bulk: 0, Total: 250
  assert.equal(calculateTotalLineDiscount(5000, 5, 9), 250);
});

test('calculateTotalLineDiscount with bulk (qty >= 10)', () => {
  // lineTotal 5000, discount 5%, qty 10
  // Regular discount: 250, amount after: 4750
  // Bulk discount (2.5% of 4750): 119, Total: 250 + 119 = 369
  assert.equal(calculateTotalLineDiscount(5000, 5, 10), 369);
});

test('calculateTotalLineDiscount with no regular discount but bulk', () => {
  // lineTotal 10000, discount 0%, qty 10
  // Regular discount: 0, amount after: 10000
  // Bulk discount (2.5% of 10000): 250, Total: 250
  assert.equal(calculateTotalLineDiscount(10000, 0, 10), 250);
});

test('invoiceTotals with bulk discount', () => {
  const invoice = {
    lines: [
      { sku: 'STICKER', name: 'Sticker', qty: 10, unitPrice: 50, vatRate: 21, discountPercent: 5 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // lineTotal: 500, regular discount (5%): 25, bulk discount (2.5% of 475): 12
  // discount: 37, amount after discount: 463
  // VAT (21% of 463): 97.23 -> 97
  // total: 500 - 37 + 97 = 560
  assert.equal(totals.subtotal, 500);
  assert.equal(totals.discount, 37);
  assert.equal(totals.vat, 97);
  assert.equal(totals.total, 560);
});

test('invoiceTotals with bulk discount on qty 100', () => {
  const invoice = {
    lines: [
      { sku: 'STICKER', name: 'Sticker', qty: 100, unitPrice: 50, vatRate: 21, discountPercent: 5 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // lineTotal: 5000, regular discount (5%): 250, amount after: 4750
  // bulk discount (2.5% of 4750): 119
  // discount: 250 + 119 = 369, amount after: 4631
  // VAT (21% of 4631): 972.51 -> 973 (banker's rounding)
  // total: 5000 - 369 + 973 = 5604
  assert.equal(totals.subtotal, 5000);
  assert.equal(totals.discount, 369);
  assert.equal(totals.vat, 973);
  assert.equal(totals.total, 5604);
});

test('invoiceTotals with bulk discount on multiple lines', () => {
  const invoice = {
    lines: [
      { sku: 'STICKER', name: 'Sticker', qty: 10, unitPrice: 50, vatRate: 21, discountPercent: 0 },
      { sku: 'PRINT', name: 'Print', qty: 9, unitPrice: 100, vatRate: 9, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line 1: 500, bulk (2.5%): 12.5 -> 12 (banker's rounding, 500*2.5/100=12.5->12)
  // Line 2: 900, no bulk (qty < 10)
  // Total discount: 12
  // Line 1 after discount: 488, VAT (21%): 102.48 -> 102
  // Line 2 after discount: 900, VAT (9%): 81
  // total: 1400 - 12 + 183 = 1571
  assert.ok(totals.discount > 0);
  assert.ok(totals.total > 1300);
});

test('invoiceTotals bulk discount with voucher', () => {
  const invoice = {
    lines: [
      { sku: 'STICKER', name: 'Sticker', qty: 10, unitPrice: 50, vatRate: 21, discountPercent: 5 },
    ],
    voucher: { code: 'TEST', amount: 50 },
  };

  const totals = invoiceTotals(invoice);
  // lineTotal: 500, regular discount: 25, bulk (2.5% of 475): 12
  // discount: 37, amount after: 463
  // VAT (21%): 97
  // total: 500 - 37 + 97 - 50 = 510
  assert.equal(totals.subtotal, 500);
  assert.equal(totals.discount, 37);
  assert.equal(totals.vat, 97);
  assert.equal(totals.voucher, 50);
  assert.equal(totals.total, 510);
});

test('invoiceTotals no bulk discount for qty exactly 9', () => {
  const invoice = {
    lines: [
      { sku: 'STICKER', name: 'Sticker', qty: 9, unitPrice: 50, vatRate: 21, discountPercent: 5 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // lineTotal: 450, regular discount (5%): 22.5 -> 22 or 23 (banker's rounding)
  // bulk: 0 (qty < 10)
  // discount should match no bulk
  assert.ok(totals.discount > 0);
  assert.ok(totals.discount <= 25); // Conservative check
});

test('invoiceTotals bulk discount applies at exactly qty 10', () => {
  const invoice10 = {
    lines: [
      { sku: 'STICKER', name: 'Sticker', qty: 10, unitPrice: 100, vatRate: 0, discountPercent: 0 },
    ],
  };

  const invoice9 = {
    lines: [
      { sku: 'STICKER', name: 'Sticker', qty: 9, unitValue: 100, vatRate: 0, discountPercent: 0 },
    ],
  };

  const totals10 = invoiceTotals(invoice10);
  // qty 10: 1000 * 2.5% = 25
  assert.equal(totals10.discount, 25);
});

