test('invoiceTotals calculates discount on a single line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 9, discountPercent: 10 }],
  }).value;
  // Line total: 9 * 8500 = 76500 cents
  // Discount: 76500 * 10 / 100 = 7650 cents (no bulk discount for qty < 10)
  // Amount after discount: 68850 cents
  // VAT (21%): 68850 * 21 / 100 = 14458.5 -> 14459 cents
  // Total: 76500 - 7650 + 14459 = 83309 cents

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 76500);
  assert.equal(totals.discount, 7650);
  assert.equal(totals.vat, 14459);
  assert.equal(totals.total, 83309);
});

test('invoiceTotals sums discounts across multiple lines', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 20 },
    ],
  }).value;
  // Line 1: 10 * 8500 = 85000, discount 10% = 8500, after discount = 76500
  // Line 2: 10 * 9500 = 95000, discount 20% = 19000, after discount = 76000
  // Total discount: 27500
  // Subtotal: 180000
  // VAT: 76500 * 21% + 76000 * 21% = 16065 + 15960 = 32025
  // Total: 180000 - 27500 + 32025 = 184525

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 180000);
  assert.equal(totals.discount, 27500);
  assert.equal(totals.vat, 32025);
  assert.equal(totals.total, 184525);
});

test('invoiceTotals handles decimal discounts with rounding', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 3, discountPercent: 12.5 }],
  }).value;
  // Line total: 3 * 8500 = 25500 cents
  // Discount: 25500 * 12.5 / 100 = 3187.5, rounded to 3188
  // Amount after discount: 25500 - 3188 = 22312
  // VAT (21%): 22312 * 21 / 100 = 4685.52, rounded to 4686
  // Total: 25500 - 3188 + 4686 = 26998

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 25500);
  assert.equal(totals.discount, 3188);
  assert.equal(totals.vat, 4686);
  assert.equal(totals.total, 26998);
});

