  // VAT (21%): 161500 * 21 / 100 = 33915 cents
  // Total: 170000 - 8500 + 33915 = 195415 cents

  const invoice = r.value;
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 170000);
  assert.equal(totals.discount, 8500);
  assert.equal(totals.vat, 33915);
  assert.equal(totals.total, 195415);
});

