test('invoiceTotals calculates discount on a single line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 9, discountPercent: 10 }],
  }).value;
  // Line total: 9 * 8500 = 76500 cents
  // Discount: 76500 * 10 / 100 = 7650 cents (no bulk discount for qty < 10)
  // Amount after discount: 68850 cents
  // VAT (21%): 68850 * 21 / 100 = 14458.5 -> 14459 cents
  // Total: 76500 - 7650 + 14459 = 83309 cents

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 76500);
  assert.equal(totals.discount, 7650);
  assert.equal(totals.vat, 14459);
  assert.equal(totals.total, 83309);
});

test('invoiceTotals sums discounts across multiple lines', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 9, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 9, discountPercent: 20 },
    ],
  }).value;
  // Line 1: 9 * 8500 = 76500, discount 10% = 7650, after discount = 68850 (no bulk)
  // Line 2: 9 * 9500 = 85500, discount 20% = 17100, after discount = 68400 (no bulk)
  // Total discount: 24750
  // Subtotal: 162000
  // VAT: 68850 * 21% = 14458.5 -> 14459, 68400 * 21% = 14364
  // VAT total: 28823
  // Total: 162000 - 24750 + 28823 = 166073

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 162000);
  assert.equal(totals.discount, 24750);
  assert.equal(totals.vat, 28823);
  assert.equal(totals.total, 166073);
});

test('invoiceTotals handles decimal discounts with rounding', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
