  // Total: 25500 - 3188 + 4686 = 26998

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 25500);
  assert.equal(totals.discount, 3188);
  assert.equal(totals.vat, 4686);
  assert.equal(totals.total, 26998);
});

