  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 1 }, // No explicit, uses tier (5%)
      { sku: 'DEV-HOUR', qty: 1, discountPercent: 0 }, // Explicit 0%
      { sku: 'STICKER', qty: 1, discountPercent: 10 }, // Explicit 10%
    ],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  assert.equal(invoice.lines[0].discountPercent, 5);
  assert.equal(invoice.lines[1].discountPercent, 0);
  assert.equal(invoice.lines[2].discountPercent, 10);
});

test('invoiceTotals correctly calculates with tier discount', () => {
  // C-001 is gold (5%)
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 9 }],
  });
  // Line total: 9 * 8500 = 76500 cents
  // Tier discount (5%): 76500 * 5 / 100 = 3825 cents (no bulk for qty < 10)
  // Amount after discount: 72675 cents
  // VAT (21%): 72675 * 21 / 100 = 15261.75 -> 15262 cents
  // Total: 76500 - 3825 + 15262 = 87937 cents

  const invoice = r.value;
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 76500);
  assert.equal(totals.discount, 3825);
  assert.equal(totals.vat, 15262);
  assert.equal(totals.total, 87937);
});

test('invoiceTotals calculates VAT on a single line', () => {
