test('calculateBulkDiscount with qty < 10', () => {
  assert.equal(calculateBulkDiscount(1000, 1), 0);
  assert.equal(calculateBulkDiscount(1000, 5), 0);
  assert.equal(calculateBulkDiscount(1000, 9), 0);
});

test('calculateBulkDiscount with qty >= 10', () => {
  // 1000 * 2.5% = 25
  assert.equal(calculateBulkDiscount(1000, 10), 25);
  assert.equal(calculateBulkDiscount(1000, 100), 25);
});

test('calculateBulkDiscount with rounding', () => {
  // 4750 * 2.5% = 118.75 -> 119 (banker's rounding)
  assert.equal(calculateBulkDiscount(4750, 10), 119);
  // 9025 * 2.5% = 225.625 -> 226 (banker's rounding)
  assert.equal(calculateBulkDiscount(9025, 10), 226);
});

test('calculateTotalLineDiscount without bulk (qty < 10)', () => {
  // lineTotal 5000, discount 5%, qty 9
  // Regular discount: 250, Bulk: 0, Total: 250
  assert.equal(calculateTotalLineDiscount(5000, 5, 9), 250);
});

test('calculateTotalLineDiscount with bulk (qty >= 10)', () => {
  // lineTotal 5000, discount 5%, qty 10
  // Regular discount: 250, amount after: 4750
  // Bulk discount (2.5% of 4750): 119, Total: 250 + 119 = 369
  assert.equal(calculateTotalLineDiscount(5000, 5, 10), 369);
});

test('calculateTotalLineDiscount with no regular discount but bulk', () => {
  // lineTotal 10000, discount 0%, qty 10
  // Regular discount: 0, amount after: 10000
