  // Line 2: 8500, discount (5%): 425, amount after: 8075, VAT (21%): 1696
  // Total discount: 12 + 425 = 437
  // Total VAT: 50 + 1696 = 1746
  assert.equal(totals.subtotal, 8750);
  assert.equal(totals.discount, 437);
  assert.equal(totals.vat, 1746);
  assert.equal(totals.total, 10059);
});

