  assert.equal(calculateTotalLineDiscount(10000, 0, 10), 250);
});

test('invoiceTotals with bulk discount', () => {
  const invoice = {
    lines: [
      { sku: 'STICKER', name: 'Sticker', qty: 10, unitPrice: 50, vatRate: 21, discountPercent: 5 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // lineTotal: 500, regular discount (5%): 25, bulk discount (2.5% of 475): 12
  // discount: 37, amount after discount: 463
  // VAT (21% of 463): 97.23 -> 97
  // total: 500 - 37 + 97 = 560
  assert.equal(totals.subtotal, 500);
  assert.equal(totals.discount, 37);
  assert.equal(totals.vat, 97);
  assert.equal(totals.total, 560);
});

