  // Total discount: 12
  // Line 1 after discount: 488, VAT (21%): 102.48 -> 102
  // Line 2 after discount: 900, VAT (9%): 81
  // total: 1400 - 12 + 183 = 1571
  assert.ok(totals.discount > 0);
  assert.ok(totals.total > 1300);
});

test('invoiceTotals bulk discount with voucher', () => {
  const invoice = {
