import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';

test('createInvoice returns a draft invoice with line details from the catalogue', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  assert.equal(invoice.customerId, 'C-001');
  assert.equal(invoice.issueDate, '2025-10-15');
  assert.equal(invoice.status, 'draft');
  assert.equal(invoice.lines.length, 1);
  assert.equal(invoice.lines[0].sku, 'DES-HOUR');
  assert.equal(invoice.lines[0].name, 'Design work (hour)');
  assert.equal(invoice.lines[0].qty, 5);
  assert.equal(invoice.lines[0].unitPrice, 8500);
  assert.equal(invoice.lines[0].vatRate, 21);
});

test('createInvoice normalizes lowercase customer ID', () => {
  const r = createInvoice({
    customerId: 'c-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
});

test('createInvoice normalizes customer ID with spaces', () => {
  const r = createInvoice({
    customerId: ' c-001 ',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
});

test('createInvoice accepts mixed case with spaces', () => {
  const r = createInvoice({
    customerId: ' C-003 ',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  assert.equal(invoice.customerId, 'C-003');
});

test('createInvoice defaults to NET30 terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  assert.equal(invoice.terms, 'NET30');
  assert.equal(invoice.dueDate, '2025-11-14');
});

test('createInvoice accepts NET14 terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  assert.equal(invoice.terms, 'NET14');
  assert.equal(invoice.dueDate, '2025-10-29');
});

test('createInvoice accepts NET30 terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET30',
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  assert.equal(invoice.terms, 'NET30');
  assert.equal(invoice.dueDate, '2025-11-14');
});

test('createInvoice accepts EOM terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  assert.equal(invoice.terms, 'EOM');
  assert.equal(invoice.dueDate, '2025-10-31');
});

test('createInvoice handles EOM on last day of month', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-31',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.dueDate, '2025-10-31');
});

test('createInvoice handles EOM in February non-leap year', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.dueDate, '2025-02-28');
});

test('createInvoice handles EOM in February leap year', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.dueDate, '2024-02-29');
});

test('createInvoice handles NET30 crossing year boundary', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET30',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.dueDate, '2026-01-14');
});

test('createInvoice rejects invalid terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'INVALID',
  });
  assert.deepEqual(r, { ok: false, error: 'TERMS_INVALID' });
});

test('createInvoice rejects uppercase NET30 as invalid (only NET14, NET30, EOM)', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'net30',
  });
  assert.deepEqual(r, { ok: false, error: 'TERMS_INVALID' });
});

test('invoiceTotals returns voucher field', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-15',
    status: 'draft',
    lines: [
      {
        sku: 'STICKER',
        name: 'Sticker sheet',
        qty: 1,
        unitPrice: 50,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.voucher, 0);
});

test('invoiceTotals deducts voucher after VAT', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-15',
    status: 'draft',
    lines: [
      {
        sku: 'STICKER',
        name: 'Sticker sheet',
        qty: 1,
        unitPrice: 50,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
    voucher: { code: 'PROMO10', amount: 5 },
  };
  // Subtotal: 50 cents
  // Discount: 0
  // VAT (21%): 50 * 21 / 100 = 10.5, rounded to 10 (banker's rounding)
  // Voucher: 5 cents
  // Total: 50 - 0 + 10 - 5 = 55 cents

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 50);
  assert.equal(totals.vat, 10);
  assert.equal(totals.voucher, 5);
  assert.equal(totals.total, 55);
});

test('applyVoucher adds voucher to draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const r = applyVoucher(invoice, { code: 'PROMO20', amount: 1000 });
  assert.equal(r.ok, true);
  const updated = r.value;
  assert.equal(updated.voucher.code, 'PROMO20');
  assert.equal(updated.voucher.amount, 1000);
});

test('applyVoucher affects invoice totals', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'STICKER', qty: 100 }],
  }).value;

  const totalsWithout = invoiceTotals(invoice);
  const r = applyVoucher(invoice, { code: 'PROMO10', amount: 500 });
  const totalsWith = invoiceTotals(r.value);

  assert.equal(totalsWith.total, totalsWithout.total - 500);
});

test('applyVoucher rejects non-draft invoice', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'STICKER', qty: 1 }],
  }).value;

  const invoice = issueInvoice(draft, []).value;
  const r = applyVoucher(invoice, { code: 'PROMO10', amount: 100 });

  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('applyVoucher rejects if voucher already applied', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-15',
