test('invoiceTotals sums multiple lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-15',
    status: 'draft',
    lines: [
      {
        sku: 'DES-HOUR',
        name: 'Design work (hour)',
        qty: 2,
        unitPrice: 8500,
        vatRate: 21,
        discountPercent: 0,
      },
      {
