import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';

test('createInvoice returns a draft invoice with line details from the catalogue', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  assert.equal(invoice.customerId, 'C-001');
  assert.equal(invoice.issueDate, '2025-10-15');
  assert.equal(invoice.status, 'draft');
  assert.equal(invoice.lines.length, 1);
  assert.equal(invoice.lines[0].sku, 'DES-HOUR');
  assert.equal(invoice.lines[0].name, 'Design work (hour)');
  assert.equal(invoice.lines[0].qty, 5);
  assert.equal(invoice.lines[0].unitPrice, 8500);
  assert.equal(invoice.lines[0].vatRate, 21);
});

test('createInvoice normalizes lowercase customer ID', () => {
  const r = createInvoice({
    customerId: 'c-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
});

test('createInvoice normalizes customer ID with spaces', () => {
  const r = createInvoice({
    customerId: ' c-001 ',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
});

test('createInvoice accepts mixed case with spaces', () => {
  const r = createInvoice({
    customerId: ' C-003 ',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  assert.equal(invoice.customerId, 'C-003');
});

test('createInvoice defaults to NET30 terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  assert.equal(invoice.terms, 'NET30');
  assert.equal(invoice.dueDate, '2025-11-14');
});

test('createInvoice accepts NET14 terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  assert.equal(invoice.terms, 'NET14');
  assert.equal(invoice.dueDate, '2025-10-29');
});

test('createInvoice accepts NET30 terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET30',
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  assert.equal(invoice.terms, 'NET30');
  assert.equal(invoice.dueDate, '2025-11-14');
});

test('createInvoice accepts EOM terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  assert.equal(invoice.terms, 'EOM');
  assert.equal(invoice.dueDate, '2025-10-31');
});

test('createInvoice handles EOM on last day of month', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-31',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.dueDate, '2025-10-31');
});

test('createInvoice handles EOM in February non-leap year', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
