    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'INVALID',
  });
  assert.deepEqual(r, { ok: false, error: 'TERMS_INVALID' });
});

test('createInvoice rejects uppercase NET30 as invalid (only NET14, NET30, EOM)', () => {
