  assert.deepEqual(r, { ok: false, error: 'TERMS_INVALID' });
});

test('invoiceTotals returns voucher field', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-15',
    status: 'draft',
    lines: [
      {
        sku: 'STICKER',
        name: 'Sticker sheet',
        qty: 1,
        unitPrice: 50,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.voucher, 0);
});

test('invoiceTotals deducts voucher after VAT', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-15',
    status: 'draft',
    lines: [
      {
        sku: 'STICKER',
        name: 'Sticker sheet',
        qty: 1,
        unitPrice: 50,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
    voucher: { code: 'PROMO10', amount: 5 },
  };
  // Subtotal: 50 cents
  // Discount: 0
  // VAT (21%): 50 * 21 / 100 = 10.5, rounded to 10 (banker's rounding)
  // Voucher: 5 cents
  // Total: 50 - 0 + 10 - 5 = 55 cents

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 50);
  assert.equal(totals.vat, 10);
  assert.equal(totals.voucher, 5);
  assert.equal(totals.total, 55);
});

test('applyVoucher adds voucher to draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const r = applyVoucher(invoice, { code: 'PROMO20', amount: 1000 });
  assert.equal(r.ok, true);
  const updated = r.value;
  assert.equal(updated.voucher.code, 'PROMO20');
  assert.equal(updated.voucher.amount, 1000);
});

test('applyVoucher affects invoice totals', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'STICKER', qty: 100 }],
  }).value;

  const totalsWithout = invoiceTotals(invoice);
  const r = applyVoucher(invoice, { code: 'PROMO10', amount: 500 });
  const totalsWith = invoiceTotals(r.value);

  assert.equal(totalsWith.total, totalsWithout.total - 500);
});

test('applyVoucher rejects non-draft invoice', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'STICKER', qty: 1 }],
  }).value;

  const invoice = issueInvoice(draft, []).value;
  const r = applyVoucher(invoice, { code: 'PROMO10', amount: 100 });

  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('applyVoucher rejects if voucher already applied', () => {
  const invoice = {
    customerId: 'C-001',
