test('invoiceTotals calculates discount on a single line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 9, discountPercent: 10 }],
  }).value;
  // Line total: 9 * 8500 = 76500 cents
  // Discount: 76500 * 10 / 100 = 7650 cents (no bulk discount for qty < 10)
  // Amount after discount: 68850 cents
  // VAT (21%): 68850 * 21 / 100 = 14458.5 -> 14458 cents (banker's rounding)
  // Total: 76500 - 7650 + 14458 = 83308 cents

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 76500);
  assert.equal(totals.discount, 7650);
  assert.equal(totals.vat, 14458);
  assert.equal(totals.total, 83308);
});

